/**
 * FarmShield AI - RecommendationSummary Component
 * 
 * Displays agronomic recommendations associated with the selected zone.
 * 
 * Scientific Integrity Rules:
 * - Display recommendations only when the backend response supports that association.
 * - Do NOT claim a recommendation is generated by AI unless the backend response supports that claim.
 * - Do NOT invent recommendations or present an unavailable recommendation as a live result.
 */

import React from 'react';
import { Lightbulb, CheckCircle2, Clock, AlertTriangle, Droplet, ArrowRight, ShieldCheck } from 'lucide-react';
import InsufficientDataState from './InsufficientDataState.jsx';

const PRIORITY_TOKENS = {
  critical: {
    color: '#EF4444',
    bg: 'rgba(239, 68, 68, 0.20)',
    border: 'rgba(239, 68, 68, 0.50)',
    label_en: 'Critical Priority',
    label_mr: 'अति तातडीचे',
  },
  high: {
    color: '#F97316',
    bg: 'rgba(249, 115, 22, 0.20)',
    border: 'rgba(249, 115, 22, 0.50)',
    label_en: 'High Priority',
    label_mr: 'महत्त्वाचे / उच्च',
  },
  medium: {
    color: '#F59E0B',
    bg: 'rgba(245, 158, 11, 0.20)',
    border: 'rgba(245, 158, 11, 0.50)',
    label_en: 'Medium Priority',
    label_mr: 'मध्यम प्राधान्य',
  },
  low: {
    color: '#22C55E',
    bg: 'rgba(34, 197, 94, 0.20)',
    border: 'rgba(34, 197, 94, 0.50)',
    label_en: 'Low Priority / Routine',
    label_mr: 'नियमित / कमी',
  },
};

export default function RecommendationSummary({
  recommendations = [],
  onNavigateIrrigationPlanner,
  onSelectRecommendation,
  currentLang = 'mr',
}) {
  const isMarathi = currentLang === 'mr';

  const formatTimestamp = (ts) => {
    if (!ts) return null;
    try {
      const d = new Date(ts);
      return `${d.toLocaleDateString()} ${d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}`;
    } catch (e) {
      return ts;
    }
  };

  return (
    <div
      className="glass-card"
      style={{
        padding: '18px',
        background: 'rgba(7, 31, 22, 0.75)',
        border: '1px solid rgba(197, 243, 107, 0.35)',
      }}
    >
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '14px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
          <div
            style={{
              width: '32px',
              height: '32px',
              borderRadius: '8px',
              background: 'rgba(197, 243, 107, 0.15)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              color: '#C5F36B',
            }}
          >
            <Lightbulb size={18} />
          </div>
          <div>
            <h3 style={{ fontSize: '15px', fontWeight: 800, color: '#FFFFFF', margin: 0 }}>
              {isMarathi ? 'कृषी सल्ला व सिंचन शिफारस' : 'Agronomic Recommendations'}
            </h3>
            <div style={{ fontSize: '11px', color: '#B6C8BB' }}>
              {isMarathi ? 'बॅकएंड डिसिजन इंजिनकडून मिळालेला सल्ला' : 'Decision rules & advisory notifications'}
            </div>
          </div>
        </div>

        {recommendations.length > 0 && (
          <span className="glass-pill" style={{ color: '#C5F36B', fontSize: '11px' }}>
            {recommendations.length} {isMarathi ? 'सक्रिय' : 'Active'}
          </span>
        )}
      </div>

      {/* Recommendations List or Empty State */}
      {recommendations.length === 0 ? (
        <InsufficientDataState
          title={isMarathi ? 'कोणतीही सक्रिय शिफारस नाही' : 'No Active Recommendations'}
          message={isMarathi 
            ? 'या विभागासाठी सध्या कोणतीही सिंचन किंवा कृषी शिफारस प्रलंबित नाही. डेटा अपुरा असल्यास किंवा परिस्थिती सामान्य असल्यास शिफारस निर्माण केली जात नाही.' 
            : 'No pending recommendations registered for this zone. When telemetry is optimal or insufficient, no advisory is raised.'}
          currentLang={currentLang}
          icon={ShieldCheck}
        />
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          {recommendations.map((rec) => {
            const priorityToken = PRIORITY_TOKENS[rec.priority] || PRIORITY_TOKENS.medium;
            const action = rec.recommended_action || {};

            return (
              <div
                key={rec.id}
                className="glass-panel"
                style={{
                  padding: '14px 16px',
                  border: `1px solid ${priorityToken.border}`,
                  background: 'rgba(10, 43, 28, 0.70)',
                  borderRadius: '16px',
                }}
              >
                {/* Priority & Status Bar */}
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '8px' }}>
                  <span
                    style={{
                      fontSize: '10.5px',
                      fontWeight: 800,
                      color: priorityToken.color,
                      background: priorityToken.bg,
                      padding: '2px 8px',
                      borderRadius: '10px',
                      border: `1px solid ${priorityToken.border}`,
                      textTransform: 'uppercase',
                    }}
                  >
                    {isMarathi ? priorityToken.label_mr : priorityToken.label_en}
                  </span>

                  <span style={{ fontSize: '11px', color: '#8E9F90', display: 'flex', alignItems: 'center', gap: '4px' }}>
                    <Clock size={11} />
                    {formatTimestamp(rec.generated_at)}
                  </span>
                </div>

                {/* Recommendation Title & Description */}
                <h4 style={{ fontSize: '15px', fontWeight: 800, color: '#FFFFFF', marginBottom: '6px' }}>
                  {isMarathi ? (rec.title || rec.title_en) : (rec.title_en || rec.title)}
                </h4>

                <p style={{ fontSize: '12.5px', color: '#D5E3D9', lineHeight: 1.45, marginBottom: '12px' }}>
                  {isMarathi ? (rec.description || rec.description_en) : (rec.description_en || rec.description)}
                </p>

                {/* Specific Action Parameters if present */}
                {(action.water_depth_mm || action.water_volume_m3 || action.recommended_window) && (
                  <div
                    style={{
                      display: 'grid',
                      gridTemplateColumns: 'repeat(auto-fit, minmax(110px, 1fr))',
                      gap: '8px',
                      padding: '10px 12px',
                      background: 'rgba(255, 255, 255, 0.05)',
                      borderRadius: '12px',
                      marginBottom: '12px',
                    }}
                  >
                    {action.water_depth_mm && (
                      <div>
                        <div style={{ fontSize: '10px', color: '#8E9F90' }}>{isMarathi ? 'पाणी खोली' : 'Depth'}</div>
                        <div style={{ fontSize: '13px', fontWeight: 800, color: '#38BDF8' }}>
                          {action.water_depth_mm} mm
                        </div>
                      </div>
                    )}

                    {action.water_volume_m3 && (
                      <div>
                        <div style={{ fontSize: '10px', color: '#8E9F90' }}>{isMarathi ? 'एकूण घनफळ' : 'Volume'}</div>
                        <div style={{ fontSize: '13px', fontWeight: 800, color: '#38BDF8' }}>
                          {action.water_volume_m3} m³
                        </div>
                      </div>
                    )}

                    {action.recommended_window && (
                      <div>
                        <div style={{ fontSize: '10px', color: '#8E9F90' }}>{isMarathi ? 'योग्य वेळ' : 'Window'}</div>
                        <div style={{ fontSize: '11px', fontWeight: 700, color: '#C5F36B' }}>
                          {action.recommended_window}
                        </div>
                      </div>
                    )}
                  </div>
                )}

                {/* Reasoning Factors List */}
                {rec.reasoning?.factors && rec.reasoning.factors.length > 0 && (
                  <div style={{ fontSize: '11px', color: '#A3B8A8', marginBottom: '12px' }}>
                    <div style={{ fontWeight: 700, color: '#C5F36B', marginBottom: '3px' }}>
                      {isMarathi ? 'कारणे व निकष:' : 'Contributing Factors:'}
                    </div>
                    <ul style={{ paddingLeft: '16px', margin: 0 }}>
                      {rec.reasoning.factors.map((f, i) => (
                        <li key={i}>{f}</li>
                      ))}
                    </ul>
                  </div>
                )}

                {/* Action Buttons: View Details & Irrigation Planner */}
                <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap', marginTop: '6px' }}>
                  {onSelectRecommendation && (
                    <button
                      onClick={() => onSelectRecommendation(rec.id)}
                      className="btn-glass-secondary"
                      style={{
                        flex: 1,
                        fontSize: '12px',
                        padding: '8px 12px',
                        minHeight: '36px',
                        color: '#C5F36B',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        gap: '6px',
                        cursor: 'pointer',
                      }}
                    >
                      <span>{isMarathi ? 'सल्ला विश्लेषण (View Evidence)' : 'Advisory Details'}</span>
                      <ArrowRight size={14} />
                    </button>
                  )}

                  {onNavigateIrrigationPlanner && action.action === 'irrigate' && (
                    <button
                      onClick={() => onNavigateIrrigationPlanner(rec)}
                      className="btn-glass-primary"
                      style={{
                        flex: 1,
                        fontSize: '12px',
                        padding: '8px 12px',
                        minHeight: '36px',
                        cursor: 'pointer',
                      }}
                    >
                      <span>{isMarathi ? 'सिंचन नियोजन (Plan)' : 'Plan Irrigation'}</span>
                      <ArrowRight size={14} />
                    </button>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

